from datetime import datetime, timezone

NAMES = ['Aarav Sharma','Diya Patel','Arjun Mehta','Ananya Rao','Vihaan Reddy','Ishita Gupta','Kabir Shah','Saanvi Iyer','Aditya Verma','Myra Nair','Rohan Das','Avni Joshi','Ishaan Kapoor','Kavya Singh','Dhruv Jain','Tara Menon','Reyansh Kumar','Nisha Roy','Dev Malhotra','Mira Desai','Ayaan Bhat','Sara Bose','Neil Sethi','Riya Anand','Aryan Sen']
CATEGORIES = ['Index Funds','Government Bonds','Fixed Deposits','ETFs','Mutual Funds','Corporate Bonds','Equities','Retirement Products','Money Market','International Equity']
GOALS = ['Wealth creation','Retirement planning','Capital preservation','Regular income','Education planning','Short-term savings','Home purchase','Emergency reserve','Travel fund','Financial independence','Legacy planning','Business capital','Debt reduction','Healthcare reserve','Diversification']
RISK = ['Conservative','Moderate','Balanced','Growth','Aggressive']
def timestamp(): return datetime.now(timezone.utc).isoformat()
def seed_data():
    investors = [dict(id=f'INV-{i+1:03}',name=n,age=28+i%30,employment='Employed',country='India',currency='INR',annual_income=900000+i*60000,monthly_income=75000+i*5000,monthly_expenses=35000,savings=500000,existing_investments=200000,debt=0,emergency_fund=210000,capital=100000+i*25000,risk=i%5+1,risk_capacity=min(5,i%5+1),horizon=[1,3,5,7,12][i%5],liquidity=i%3+1,goal=GOALS[i%6],experience='Intermediate',knowledge='Intermediate',loss_reaction='Hold',excluded=[],preferences=[],esg=False,consent=True,created_at=timestamp()) for i,n in enumerate(NAMES)]
    products=[]
    for i in range(30):
        cat=CATEGORIES[i%10]; risk=[3,1,1,3,4,2,5,3,1,5][i%10]; horizon=[5,3,1,5,7,3,7,10,1,7][i%10]
        products.append(dict(id=f'PRD-{i+1:03}',name=f'{["Meridian","Atlas","Horizon"][i//10]} {cat if cat!="ETFs" else "Broad Market ETF"}',category=cat,provider=['Meridian Capital','Atlas Investments','Horizon Financial'][i//10],asset_class=cat,risk=risk,volatility=[12,3,0,14,18,6,25,10,1,23][i%10],minimum=[500,1000,10000][i%3],maximum=None,horizon=horizon,liquidity=3 if cat=='Fixed Deposits' else 1 if cat in ['ETFs','Money Market','Equities'] else 2,fee=round(.12+(i%7)*.18,2),exit_charge=0 if i%2 else 1,currency='INR',geography='India' if i%10!=9 else 'Global',goals=[GOALS[0],GOALS[1]] if risk>=3 else [GOALS[2],GOALS[3],GOALS[5]],status='Active',regulation='Synthetic demonstration disclosure; not a registered offering',benchmark='Not available — synthetic product',updated_at=timestamp()))
    documents=[dict(id=f'DOC-{i+1:03}',name=f'{CATEGORIES[i]} — sample disclosure.txt',category='Product disclosure',product_id=products[i]['id'],text=f'SYNTHETIC EDUCATIONAL DOCUMENT. {products[i]["name"]} is a sample {CATEGORIES[i]} product. Risk category {products[i]["risk"]} of 5. Minimum investment INR {products[i]["minimum"]}. Minimum horizon {products[i]["horizon"]} years. Annual expense ratio {products[i]["fee"]} percent. Liquidity level {products[i]["liquidity"]} (1 liquid, 3 restricted). Capital is at risk; returns are not guaranteed. These sample attributes are demonstration parameters, not verified market information.',created_at=timestamp()) for i in range(10)]
    return investors,products,documents
